--
-- Threads (slug — target libraries):
--   1. isaiah-62-thou-shalt-be-called-by-a-new-name — NT (Revelation 2, Revelation 3) [free]
--      (★★ the new name the mouth of Yahuah names; the white stone, the new name written on the overcomer)
--   2. isaiah-62-no-more-forsaken-but-hephzibah-and-beulah — Tanakh (Hosea 1, Hosea 2) [free]
--      (★★ the two-house reversal: Forsaken/Desolate → Delighted-in/Married, Lo-Ammi → Ammi; the SAME divorced wife restored)
--   3. isaiah-62-as-the-bridegroom-rejoiceth-over-the-bride — NT (Revelation 19, Revelation 21) [free]
--      (★ the bridegroom and bride; the Formed Son the bridegroom, restored Yashar'el the bride; the marriage of the Lamb)
--   4. isaiah-62-watchmen-on-thy-walls-the-holy-people-the-redeemed — NT (1 Peter 2) [free]
--      (★ the ceaseless watchmen establishing Jerusalem; the holy people / redeemed / peculiar people, Lo-Ammi→Ammi)
--   5. isaiah-62-behold-thy-salvation-cometh-his-reward-is-with-him — NT (Revelation 22) [free]
--      (★★ the coming One; thy salvation cometh, his reward with him → I come quickly, my reward is with me)
--
-- Framing notes:
--   ★★ THE NEW NAME (THREAD 1): *thou shalt be called by a new name, which the mouth of Yahuah
--      (LORD) shall name* (62:2). The renamed bride of v.4 (Hephzi-bah) is the restored people, and
--      the Revelation overcomer receives that very gift: *To him that overcometh will I give to eat
--      of the hidden manna, and will give him a white stone, and in the stone a new name written*
--      (Rev 2:17); *I will write upon him the name of my Elohim (God), and the name of the city of
--      my Elohim (God), which is new Jerusalem... and I will write upon him my new name* (Rev 3:12).
--      The mouth of Yahuah names the restored bride; the Formed Son writes his new name on the
--      overcomer.
--   ★★ NO MORE FORSAKEN (THREAD 2): *Thou shalt no more be termed Forsaken... but thou shalt be
--      called Hephzi-bah [my-delight-is-in-her], and thy land Beulah [married]: for Yahuah (LORD)
--      delighteth in thee, and thy land shall be married* (62:4). This is the explicit two-house
--      reversal of Hosea: the northern wife was divorced and named Lo-ruhamah (*I will no more have
--      mercy*, Hos 1:6) and Lo-ammi (*ye are not my people*, Hos 1:9) — yet *in the place where it
--      was said unto them, Ye are not my people, there it shall be said unto them, Ye are the sons
--      of the living Elohim (God)* (Hos 1:10), and *I will say to them which were not my people,
--      Thou art my people* (Hos 2:23), the betrothal restored: *I will betroth thee unto me for
--      ever* (Hos 2:19). Forsaken/Desolate become Delighted-in/Married; Lo-Ammi becomes Ammi. NOT
--      a new people replacing the old — the SAME scattered, divorced wife of the covenant restored.
--   ★ THE BRIDEGROOM AND THE BRIDE (THREAD 3): *as the bridegroom rejoiceth over the bride, so
--      shall thy Elohim (God) rejoice over thee* (62:5). The restoration consummates in the
--      Revelation marriage: *the marriage of the Lamb is come, and his wife hath made herself
--      ready* (Rev 19:7); *the holy city, new Jerusalem, coming down from Elohim (God) out of
--      heaven, prepared as a bride adorned for her husband* (Rev 21:2). The Formed Son is the
--      bridegroom; the restored Yashar'el — the renamed, remarried Beulah-land — is the bride.
--   ★ THE WATCHMEN / THE HOLY PEOPLE (THREAD 4): *I have set watchmen upon thy walls, O Jerusalem,
--      which shall never hold their peace day nor night... give him no rest, till he establish, and
--      till he make Jerusalem a praise in the earth* (62:6-7) — the ceaseless intercessors. And
--      the end of it: *they shall call them, The holy people, The redeemed of Yahuah (LORD): and
--      thou shalt be called, Sought out, A city not forsaken* (62:12). Peter names this restored
--      remnant: *ye are a chosen generation, a royal priesthood, an holy nation, a peculiar people*
--      (1 Pet 2:9), *which in time past were not a people, but are now the people of Elohim (God):
--      which had not obtained mercy, but now have obtained mercy* (1 Pet 2:10) — the Lo-Ammi→Ammi /
--      Lo-Ruhamah→Ruhamah reversal of Hosea applied to the holy people, the redeemed, the city no
--      longer forsaken. Peculiar people = Yashar'el restored, not a church replacing her.
--   ★★ THY SALVATION COMETH (THREAD 5): *Behold, Yahuah (LORD) hath proclaimed unto the end of the
--      world, Say ye to the daughter of Zion, Behold, thy salvation cometh; behold, his reward is
--      with him, and his work before him* (62:11). The book of Revelation closes on that very
--      promise from the coming One's own mouth: *behold, I come quickly; and my reward is with me,
--      to give every man according as his work shall be* (Rev 22:12). The salvation that comes to
--      the daughter of Zion is the Formed Son, the reward in his hand.
--   VERSES WITH NO SEPARATE ADD: v.1 (Zion's sake / I will not rest — the resolve the watchmen take
--      up, woven into THREAD 4), v.3 (crown of glory / royal diadem — woven into THREAD 1/3 prose),
--      v.8-9 (the sworn reversal of the curse — woven into THREAD 4 prose), v.10 (go through the
--      gates / lift up a standard — the gathering signal, THREAD 4 prose). All recorded, none
--      silently skipped.

CREATE TEMP VIEW _s303_isa62_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id=c.id JOIN books b ON c.book_id=b.id
  JOIN editions e ON b.edition_id=e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29');

INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM (VALUES
    -- THREAD 1 (★★): thou shalt be called by a new name — the new name given to the overcomer
    ('canon','isaiah',62,2,'canon','revelation',2,17,'free',
      E'*He that hath an ear, let him hear what the Spirit saith unto the churches; To him that overcometh will I give to eat of the hidden manna, and will give him a white stone, and in the stone a new name written, which no man knoweth saving he that receiveth it* (Revelation 2:17). The renamed bride of Zion — *thou shalt be called by a new name, which the mouth of Yahuah (LORD) shall name* (Isaiah 62:2) — is the overcomer who receives *a white stone, and in the stone a new name written*. The mouth of Yahuah names the restored people; the new name is the gift of the One who renames.'),
    ('canon','isaiah',62,2,'canon','revelation',3,12,'free',
      E'*Him that overcometh will I make a pillar in the temple of my Elohim (God)... and I will write upon him the name of my Elohim (God), and the name of the city of my Elohim (God), which is new Jerusalem, which cometh down out of heaven from my Elohim (God): and I will write upon him my new name* (Revelation 3:12). The promise *thou shalt be called by a new name, which the mouth of Yahuah (LORD) shall name* (Isaiah 62:2) is fulfilled when the Formed Son writes upon the overcomer *my new name* — the name of the new Jerusalem, the renamed and remarried city, written on her own.'),

    -- THREAD 2 (★★): no more Forsaken but Hephzibah and Beulah — the two-house Lo-Ammi reversal
    ('canon','isaiah',62,4,'canon','hosea',1,10,'free',
      E'*Yet the number of the children of Yashar''el (Israel) shall be as the sand of the sea, which cannot be measured nor numbered; and it shall come to pass, that in the place where it was said unto them, Ye are not my people, there it shall be said unto them, Ye are the sons of the living Elohim (God)* (Hosea 1:10). The reversal *Thou shalt no more be termed Forsaken... but thou shalt be called Hephzi-bah* (Isaiah 62:4) is Hosea''s very reversal of the divorced northern house: where she was named *not my people*, there *it shall be said... Ye are the sons of the living Elohim (God)*. The same scattered wife — never a replacement — renamed and reclaimed.'),
    ('canon','isaiah',62,4,'canon','hosea',2,23,'free',
      E'*And I will sow her unto me in the earth; and I will have mercy upon her that had not obtained mercy; and I will say to them which were not my people, Thou art my people; and they shall say, Thou art my Elohim (God)* (Hosea 2:23). The land that *shall no more be termed... Desolate* and is now *Beulah* — *married* (Isaiah 62:4) — is the Lo-ruhamah/Lo-ammi house brought home: *I will have mercy upon her that had not obtained mercy... I will say to them which were not my people, Thou art my people*. Forsaken becomes Delighted-in; Lo-Ammi becomes Ammi.'),
    ('canon','isaiah',62,4,'canon','hosea',2,19,'free',
      E'*And I will betroth thee unto me for ever; yea, I will betroth thee unto me in righteousness, and in judgment, and in lovingkindness, and in mercies* (Hosea 2:19). The land *married* and the people *delighted* in — *for Yahuah (LORD) delighteth in thee, and thy land shall be married* (Isaiah 62:4) — is the betrothal Hosea promised the divorced wife: *I will betroth thee unto me for ever... in righteousness, and in judgment, and in lovingkindness, and in mercies*. The remarriage of the scattered house, restored to her first husband.'),

    -- THREAD 3 (★): as the bridegroom rejoiceth over the bride — the bridegroom and the bride
    ('canon','isaiah',62,5,'canon','revelation',19,7,'free',
      E'*Let us be glad and rejoice, and give honour to him: for the marriage of the Lamb is come, and his wife hath made herself ready* (Revelation 19:7). The promise *as the bridegroom rejoiceth over the bride, so shall thy Elohim (God) rejoice over thee* (Isaiah 62:5) consummates in the marriage of the Lamb: the bridegroom is the Formed Son, *the marriage of the Lamb is come, and his wife hath made herself ready* — the restored Yashar''el made ready as his bride.'),
    ('canon','isaiah',62,5,'canon','revelation',21,2,'free',
      E'*And I John saw the holy city, new Jerusalem, coming down from Elohim (God) out of heaven, prepared as a bride adorned for her husband* (Revelation 21:2). The rejoicing *as the bridegroom rejoiceth over the bride* (Isaiah 62:5) is the holy city herself: *new Jerusalem... prepared as a bride adorned for her husband*. The renamed, remarried Beulah-land of Isaiah 62 is the bride-city descending from heaven, adorned for the Formed Son her husband.'),

    -- THREAD 4 (★): watchmen on thy walls / the holy people, the redeemed — Lo-Ammi→Ammi
    ('canon','isaiah',62,12,'canon','1-peter',2,9,'free',
      E'*But ye are a chosen generation, a royal priesthood, an holy nation, a peculiar people; that ye should shew forth the praises of him who hath called you out of darkness into his marvellous light* (1 Peter 2:9). The names given the restored city — *they shall call them, The holy people, The redeemed of Yahuah (LORD)... A city not forsaken* (Isaiah 62:12) — are Peter''s names for the same restored remnant: *a chosen generation, a royal priesthood, an holy nation, a peculiar people*. The holy people of Zion, not a church replacing her.'),
    ('canon','isaiah',62,12,'canon','1-peter',2,10,'free',
      E'*Which in time past were not a people, but are now the people of Elohim (God): which had not obtained mercy, but now have obtained mercy* (1 Peter 2:10). The city that *shalt be called, Sought out, A city not forsaken* (Isaiah 62:12) is the Lo-Ammi house restored: *in time past were not a people, but are now the people of Elohim (God); which had not obtained mercy, but now have obtained mercy* — Peter quoting Hosea''s very reversal over the holy people, the redeemed, the no-longer-forsaken.'),

    -- THREAD 5 (★★): behold thy salvation cometh, his reward is with him — the coming One
    ('canon','isaiah',62,11,'canon','revelation',22,12,'free',
      E'*And, behold, I come quickly; and my reward is with me, to give every man according as his work shall be* (Revelation 22:12). The proclamation to the daughter of Zion — *Behold, thy salvation cometh; behold, his reward is with him, and his work before him* (Isaiah 62:11) — is the coming One''s own closing word: *I come quickly; and my reward is with me, to give every man according as his work shall be*. The salvation that comes to Zion is the Formed Son, the reward in his hand.')
  ) AS i(src_edition,src_slug,src_ch,src_v,tgt_edition,tgt_slug,tgt_ch,tgt_v,tier,note)
  JOIN _s303_isa62_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _s303_isa62_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

-- THREAD 1 (★★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-62-thou-shalt-be-called-by-a-new-name',
       E'Thou shalt be called by a new name — the new name the mouth of Yahuah shall name',
       E'The restoration crown of Zion carries a renaming: *And the Gentiles shall see thy righteousness, and all kings thy glory: and thou shalt be called by a new name, which the mouth of Yahuah (LORD) shall name. Thou shalt also be a crown of glory in the hand of Yahuah (LORD), and a royal diadem in the hand of thy Elohim (God)* (Isaiah 62:2-3). The new name is given at the very mouth of Yahuah — and the Formed Son gives that gift to the overcomer. To Pergamos: *To him that overcometh will I give to eat of the hidden manna, and will give him a white stone, and in the stone a new name written, which no man knoweth saving he that receiveth it* (Revelation 2:17). And to Philadelphia: *Him that overcometh will I make a pillar in the temple of my Elohim (God), and he shall go no more out: and I will write upon him the name of my Elohim (God), and the name of the city of my Elohim (God), which is new Jerusalem, which cometh down out of heaven from my Elohim (God): and I will write upon him my new name* (Revelation 3:12). The renamed city of Isaiah 62 (Hephzi-bah, Beulah) and the new name written on the overcomer are one gift — the mouth of Yahuah names the restored bride, and the Formed Son writes his new name upon her own.',
       sv.verse_id, ev.verse_id, 'free', 27525
  FROM _s303_isa62_lookup sv, _s303_isa62_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=62 AND sv.verse_number=2
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=62 AND ev.verse_number=3
ON CONFLICT (slug) DO NOTHING;

-- THREAD 2 (★★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-62-no-more-forsaken-but-hephzibah-and-beulah',
       E'No more Forsaken but Hephzi-bah and Beulah — the two-house wife restored',
       E'The renaming of Zion is the explicit reversal of Hosea''s divorce of the northern house: *Thou shalt no more be termed Forsaken; neither shall thy land any more be termed Desolate: but thou shalt be called Hephzi-bah, and thy land Beulah: for Yahuah (LORD) delighteth in thee, and thy land shall be married* (Isaiah 62:4) — Hephzi-bah, *my-delight-is-in-her*; Beulah, *married*. Hosea was made to name the divorced wife''s children for the verdict: *Call her name Lo-ruhamah: for I will no more have mercy upon the house of Yashar''el (Israel)* (Hosea 1:6), and *Call his name Lo-ammi: for ye are not my people* (Hosea 1:9). Yet the same prophet promised the reversal: *in the place where it was said unto them, Ye are not my people, there it shall be said unto them, Ye are the sons of the living Elohim (God)* (Hosea 1:10); *I will betroth thee unto me for ever; yea, I will betroth thee unto me in righteousness, and in judgment, and in lovingkindness, and in mercies* (Hosea 2:19); *I will have mercy upon her that had not obtained mercy; and I will say to them which were not my people, Thou art my people* (Hosea 2:23). Forsaken becomes Delighted-in; Desolate becomes Married; Lo-Ammi becomes Ammi. This is NOT a new people grafted in to replace the old — it is the SAME scattered, divorced two-house wife, renamed and remarried to her first husband.',
       sv.verse_id, ev.verse_id, 'free', 27528
  FROM _s303_isa62_lookup sv, _s303_isa62_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=62 AND sv.verse_number=4
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=62 AND ev.verse_number=4
ON CONFLICT (slug) DO NOTHING;

-- THREAD 3 (★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-62-as-the-bridegroom-rejoiceth-over-the-bride',
       E'As the bridegroom rejoiceth over the bride — the marriage of the Lamb',
       E'The remarriage of the renamed, married land breaks into rejoicing: *For as a young man marrieth a virgin, so shall thy sons marry thee: and as the bridegroom rejoiceth over the bride, so shall thy Elohim (God) rejoice over thee* (Isaiah 62:5). The Formed Son is the bridegroom, and the restored Yashar''el his bride — and the Revelation consummates it: *Let us be glad and rejoice, and give honour to him: for the marriage of the Lamb is come, and his wife hath made herself ready* (Revelation 19:7). The bride is the holy city herself: *And I John saw the holy city, new Jerusalem, coming down from Elohim (God) out of heaven, prepared as a bride adorned for her husband* (Revelation 21:2). The Beulah-land of Isaiah 62 — *married*, delighted in — is the new Jerusalem adorned as a bride; the rejoicing of the bridegroom over the bride is the joy of the Formed Son over the people he renames, remarries, and brings home.',
       sv.verse_id, ev.verse_id, 'free', 27531
  FROM _s303_isa62_lookup sv, _s303_isa62_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=62 AND sv.verse_number=5
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=62 AND ev.verse_number=5
ON CONFLICT (slug) DO NOTHING;

-- THREAD 4 (★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-62-watchmen-on-thy-walls-the-holy-people-the-redeemed',
       E'Watchmen on thy walls — the holy people, the redeemed, a city not forsaken',
       E'Set over the renamed city are ceaseless intercessors: *I have set watchmen upon thy walls, O Jerusalem, which shall never hold their peace day nor night: ye that make mention of Yahuah (LORD), keep not silence, And give him no rest, till he establish, and till he make Jerusalem a praise in the earth* (Isaiah 62:6-7). The chapter ends in the new names the gathered receive: *And they shall call them, The holy people, The redeemed of Yahuah (LORD): and thou shalt be called, Sought out, A city not forsaken* (Isaiah 62:12). Peter names this same restored remnant with the same titles: *But ye are a chosen generation, a royal priesthood, an holy nation, a peculiar people; that ye should shew forth the praises of him who hath called you out of darkness into his marvellous light* (1 Peter 2:9), *Which in time past were not a people, but are now the people of Elohim (God): which had not obtained mercy, but now have obtained mercy* (1 Peter 2:10). That is Hosea''s Lo-Ammi→Ammi and Lo-Ruhamah→Ruhamah reversal carried onto the holy people, the redeemed, the city no longer forsaken — the peculiar people who are Yashar''el restored, not a church set in her place.',
       sv.verse_id, ev.verse_id, 'free', 27534
